"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[8328],{65766(a,n,e){e.r(n),e.d(n,{assets:()=>m,contentTitle:()=>u,default:()=>d,frontMatter:()=>t,metadata:()=>i,toc:()=>k});const i=JSON.parse('{"id":"learning/courses/integrating-quantum-and-high-performance-computing/introduction","title":"Pengenalan","description":"Pelajaran ini memperkenalkan kursus mengintegrasikan pengkomputeran kuantum dan prestasi tinggi serta merangkumi garis besar kursus.","source":"@site/i18n/ms/docusaurus-plugin-content-docs/current/learning/courses/integrating-quantum-and-high-performance-computing/introduction.mdx","sourceDirName":"learning/courses/integrating-quantum-and-high-performance-computing","slug":"/learning/courses/integrating-quantum-and-high-performance-computing/introduction","permalink":"/learning/courses/integrating-quantum-and-high-performance-computing/introduction","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/integrating-quantum-and-high-performance-computing/introduction.mdx","tags":[],"version":"current","frontMatter":{"title":"Pengenalan","sidebar_label":"Pengenalan","description":"Pelajaran ini memperkenalkan kursus mengintegrasikan pengkomputeran kuantum dan prestasi tinggi serta merangkumi garis besar kursus.","notebook_path":"learning/courses/integrating-quantum-and-high-performance-computing/introduction.ipynb"},"sidebar":"tutorialsSidebar","previous":{"title":"Gambaran Keseluruhan","permalink":"/learning/courses/integrating-quantum-and-high-performance-computing/"},"next":{"title":"Sumber pengiraan","permalink":"/learning/courses/integrating-quantum-and-high-performance-computing/compute-resources"}}');var r=e(74848),s=e(28453);const t={title:"Pengenalan",sidebar_label:"Pengenalan",description:"Pelajaran ini memperkenalkan kursus mengintegrasikan pengkomputeran kuantum dan prestasi tinggi serta merangkumi garis besar kursus.",notebook_path:"learning/courses/integrating-quantum-and-high-performance-computing/introduction.ipynb"},u=void 0,m={},k=[{value:"Selamat Datang ke Sempadan",id:"welcome-to-the-frontier",level:2},{value:"HPC",id:"hpc",level:3},{value:"Pengkomputeran kuantum",id:"quantum-computing",level:3},{value:"Pendekatan hibrid",id:"a-hybrid-approach",level:3},{value:"Mengapa kita melangkau pengkomputeran klasik",id:"mengapa-kita-melangkau-pengkomputeran-klasik",level:2},{value:"Mengapa bukan kuantum sahaja?",id:"mengapa-bukan-kuantum-sahaja",level:2},{value:"Seni bina baharu",id:"new-architecture",level:2},{value:"Persediaan yang disyorkan",id:"persediaan-yang-disyorkan",level:2},{value:"Bagi mereka yang baru dalam HPC",id:"for-those-new-to-hpc",level:3},{value:"Bagi mereka yang baru dalam kuantum",id:"for-those-new-to-quantum",level:3},{value:"Tentang kursus ini",id:"tentang-kursus-ini",level:2},{value:"Garis besar kursus",id:"garis-besar-kursus",level:3},{value:"Rujukan",id:"rujukan",level:2}];function l(a){const n={a:"a",annotation:"annotation",h2:"h2",h3:"h3",img:"img",li:"li",math:"math",mn:"mn",mrow:"mrow",msup:"msup",p:"p",semantics:"semantics",span:"span",ul:"ul",...(0,s.R)(),...a.components},{IBMVideo:i}=n;return i||function(a,n){throw new Error("Expected "+(n?"component":"object")+" `"+a+"` to be defined: you likely forgot to import, pass, or provide it.")}("IBMVideo",!0),(0,r.jsxs)(r.Fragment,{children:["\n","\n",(0,r.jsx)(n.h2,{id:"welcome-to-the-frontier",children:"Selamat Datang ke Sempadan"}),"\n",(0,r.jsx)(n.p,{children:"Sepanjang sejarah, pemahaman saintifik kita tentang dunia berkembang pesat apabila alat-alat baru tersedia \u2014 alat yang membolehkan kita bertanya soalan baru, menjalankan eksperimen yang lebih besar, dan menyiasat kawasan penyelidikan baru. Antara alat-alat tersebut ialah teleskop, mikroskop, dan Large Hadron Collider. Setiap satu memberi akses kepada jenis penemuan saintifik yang baru. Pada tahun 1960-an, kita juga menyaksikan pembangunan pengkomputeran prestasi tinggi (HPC), yang menjadi alat penting untuk menyelesaikan tugas pengkomputeran yang kompleks, termasuk banyak cabaran saintifik yang penting."}),"\n",(0,r.jsx)(n.p,{children:"Kini kita mempunyai alat penting lain untuk kemajuan saintifik: komputer kuantum. Walaupun masih merupakan teknologi yang baru muncul, komputer kuantum berpotensi mengubah secara ketara jenis masalah pengkomputeran yang boleh kita selesaikan dengan cekap. Kursus ini berkaitan dengan memahami bagaimana teknologi-teknologi ini, yang bekerja bersama, boleh mengembangkan sempadan apa yang mungkin secara komputasi."}),"\n",(0,r.jsx)(n.p,{children:"Misi kita jelas tetapi bercita-cita tinggi: untuk membekalkan Anda dengan pengetahuan konsep dan praktikal yang diperlukan untuk menggunakan teknologi-teknologi ini bagi menangani beberapa masalah paling sukar di dunia."}),"\n",(0,r.jsx)(n.p,{children:"Video ini menggambarkan matlamat kursus ini dan motivasi di sebalik menggabungkan HPC dan pengkomputeran kuantum."}),"\n",(0,r.jsx)(i,{id:"134680662",title:"Dalam video ini, Iskandar Sitdikov memperkenalkan HPC dan pengkomputeran kuantum, termasuk beberapa bidang aplikasi yang menjanjikan."}),"\n",(0,r.jsx)(n.h3,{id:"hpc",children:"HPC"}),"\n",(0,r.jsx)(n.p,{children:"Apakah sebenarnya pengkomputeran prestasi tinggi? Pengkomputeran prestasi tinggi telah menjadi asas untuk menyelesaikan masalah pengkomputeran moden. Kita tidak lagi hidup di zaman di mana masalah-masalah canggih boleh diselesaikan dengan alat mudah seperti sempoa atau pen dan kertas; sebaliknya, kita berurusan dengan soalan dan set data yang memerlukan kuasa pengkomputeran yang sangat besar."}),"\n",(0,r.jsx)(n.p,{children:"Bidang pengkomputeran prestasi tinggi boleh ditelusuri asal-usulnya kepada pembangunan superkomputer terawal pada tahun 1960-an. Ini adalah mesin yang direka khas untuk menyelesaikan masalah saintifik dan kejuruteraan berskala besar dengan lebih cepat daripada komputer konvensional."}),"\n",(0,r.jsx)(n.p,{children:"Salah satu superkomputer terawal yang terkenal ialah CDC 6600 (1964), yang dibina oleh Seymour Cray, sering dirujuk sebagai bapa superkomputer. CDC 6600 adalah komputer terpantas pada zamannya, menggunakan seni bina inovatif yang merangkumi unit berfungsi selari dan pemipaan \u2014 konsep yang masih digunakan dalam HPC hari ini."}),"\n",(0,r.jsx)(n.p,{children:"Cray terus memajukan bidang ini dengan Cray-1 (1976), yang memperkenalkan pemprosesan vektor \u2014 teknik yang sangat meningkatkan kelajuan operasi pada tatasusunan data yang besar, menjadikannya sesuai untuk pengkomputeran saintifik."}),"\n",(0,r.jsx)(n.p,{children:"Apabila kelajuan pemproses tunggal mula mencapah, HPC berkembang ke arah pengkomputeran selari \u2014 menggunakan banyak pemproses yang bekerja bersama pada bahagian masalah yang berbeza. Semasa tahun 1980-an dan 1990-an, seni bina selari menjadi biasa dalam HPC. Menjelang awal 2000-an, HPC beralih kepada kluster perkakasan komoditi, iaitu pelayan biasa yang disambungkan oleh rangkaian berkelajuan tinggi. Peralihan ini menjadikan superkomputer lebih berpatutan dan memberi akses yang lebih luas kepada HPC."}),"\n",(0,r.jsx)(n.p,{children:"Sepanjang evolusi ini, IBM\xae berada di barisan hadapan dalam penyelidikan dan pelaksanaan HPC. Terutamanya, superkomputer IBM Blue Gene adalah salah satu keluarga superkomputer paling berpengaruh pada tahun 2000-an dan awal 2010-an. Ini adalah era pertumbuhan besar dalam sistem selari besar-besaran, di mana Blue Gene/Q adalah contohnya, dengan satu contoh (Sequoia) mempunyai 100,000 nod. IBM-built Oak Ridge Summit adalah sumber HPC pertama yang mencapai ExaOPS (1.88 ketepatan campuran) pada 2018."}),"\n",(0,r.jsxs)(n.p,{children:["Hari ini, kita berada dalam era exascale, di mana superkomputer boleh melakukan ",(0,r.jsxs)(n.span,{className:"katex",children:[(0,r.jsx)(n.span,{className:"katex-mathml",children:(0,r.jsx)(n.math,{xmlns:"http://www.w3.org/1998/Math/MathML",children:(0,r.jsxs)(n.semantics,{children:[(0,r.jsx)(n.mrow,{children:(0,r.jsxs)(n.msup,{children:[(0,r.jsx)(n.mn,{children:"10"}),(0,r.jsx)(n.mn,{children:"18"})]})}),(0,r.jsx)(n.annotation,{encoding:"application/x-tex",children:"10^{18}"})]})})}),(0,r.jsx)(n.span,{className:"katex-html","aria-hidden":"true",children:(0,r.jsxs)(n.span,{className:"base",children:[(0,r.jsx)(n.span,{className:"strut",style:{height:"0.8141em"}}),(0,r.jsx)(n.span,{className:"mord",children:"1"}),(0,r.jsxs)(n.span,{className:"mord",children:[(0,r.jsx)(n.span,{className:"mord",children:"0"}),(0,r.jsx)(n.span,{className:"msupsub",children:(0,r.jsx)(n.span,{className:"vlist-t",children:(0,r.jsx)(n.span,{className:"vlist-r",children:(0,r.jsx)(n.span,{className:"vlist",style:{height:"0.8141em"},children:(0,r.jsxs)(n.span,{style:{top:"-3.063em",marginRight:"0.05em"},children:[(0,r.jsx)(n.span,{className:"pstrut",style:{height:"2.7em"}}),(0,r.jsx)(n.span,{className:"sizing reset-size6 size3 mtight",children:(0,r.jsx)(n.span,{className:"mord mtight",children:(0,r.jsx)(n.span,{className:"mord mtight",children:"18"})})})]})})})})})]})]})})]})," operasi sesaat (exaflops). Superkomputer pertama yang mampu mencapai pencapaian ini ialah Frontier, yang terletak di Oak Ridge National Laboratory."]}),"\n",(0,r.jsx)(n.p,{children:"Jadi mengapa kita memerlukan sumber pengkomputeran yang begitu berkuasa? Terdapat masalah yang kritikal kepada kesejahteraan manusia yang memerlukan sumber yang sangat tinggi untuk dimodelkan atau diselesaikan. Contohnya termasuk model iklim, kajian struktur dan pergerakan mantel Bumi, dan simulasi dinamik bendalir."}),"\n",(0,r.jsxs)(n.p,{children:["Banyak masalah jenis ini telah ditangani oleh Penyelidik IBM dan rakan kerja yang bekerja pada sistem IBM. Kepimpinan yang berterusan ini telah diiktiraf secara meluas. Sebagai contoh, penyelidik IBM telah memenangi Anugerah Gordon Bell sebanyak enam kali.",(0,r.jsx)(n.a,{href:"#references",children:"[1]"})]}),"\n",(0,r.jsxs)(n.p,{children:["HPC adalah domain yang sangat aktif dengan sempadan yang sentiasa dipecahkan. Untuk satu gambaran keseluruhan keupayaan moden, lihat ",(0,r.jsx)(n.a,{href:"https://top500.org/lists/top500/2025/06/",children:"senarai ini"})," dari 500 superkomputer teratas."]}),"\n",(0,r.jsx)(n.h3,{id:"quantum-computing",children:"Pengkomputeran kuantum"}),"\n",(0,r.jsxs)(n.p,{children:["Pengkomputeran kuantum adalah paradigma pengkomputeran baru yang tidak sekadar mengikuti perkembangan beransur-ansur komputer klasik. Ia bertujuan untuk memanfaatkan sifat kuantum superposisi, jalinan, dan interferens kuantum untuk menyelesaikan masalah yang tidak dapat diselesaikan oleh komputer klasik sahaja. Kita tidak akan meneroka perincian keunikan pengkomputeran kuantum dalam kursus ini \u2014 lihat ",(0,r.jsx)(n.a,{href:"/learning/courses/fundamentals-of-quantum-algorithms/index",children:"Asas maklumat kuantum"})," untuk maklumat lanjut \u2014 tetapi sebaliknya kita akan membincangkan bagaimana menggabungkan dua infrastruktur ini boleh membawa kepada terobosan dalam sains gunaan."]}),"\n",(0,r.jsx)(n.h3,{id:"a-hybrid-approach",children:"Pendekatan hibrid"}),"\n",(0,r.jsx)(n.p,{children:"Yang paling penting untuk ditekankan ialah kedua-dua paradigma pengkomputeran ini bukan pesaing. Kita berada dalam era di mana aliran kerja yang dioptimumkan memerlukan kedua-dua paradigma untuk saling melengkapi dan menempatkan tugas di tempat yang paling berkesan dikendalikan. Komputer kuantum tidak akan menggantikan sistem klasik; sebaliknya, masa depan sains pengkomputeran akan semakin bergantung kepada aliran kerja hibrid di mana HPC menyediakan pemprosesan klasik berprestasi tinggi, dan pengkomputeran kuantum menyumbangkan keupayaan unik. Sebagai pengamal, penyelidik, atau ahli teknologi, memahami cara menggabungkan alat-alat ini akan menempatkan Anda sebagai pemimpin dalam era saintifik dan teknologi seterusnya."}),"\n",(0,r.jsx)(n.p,{children:"Kita akan mengkaji bagaimana pengkomputeran kuantum dan HPC diposisikan untuk membolehkan terobosan merentasi pelbagai industri, termasuk:"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Kimia: Mempercepatkan pengenalpastian ubat-ubatan dan bahan baru."}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Tenaga: Mereka bentuk pemangkin, bateri, dan penyelesaian tenaga bersih yang lebih baik."}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Kewangan: Memodelkan risiko, mengoptimumkan portfolio, dan membangunkan instrumen kewangan baru."}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"AI & Pembelajaran Mesin: Meningkatkan latihan model, pengoptimuman, dan analisis data."}),"\n"]}),"\n"]}),"\n",(0,r.jsx)(n.h2,{id:"mengapa-kita-melangkau-pengkomputeran-klasik",children:"Mengapa kita melangkau pengkomputeran klasik"}),"\n",(0,r.jsx)(n.p,{children:"Manusia telah mencapai kejayaan yang ketara dalam bidang aplikasi di atas menggunakan HPC. Walau bagaimanapun, walaupun superkomputer terpantas di dunia menghadapi kesukaran apabila masalah berskala secara faktorial atau eksponen dengan saiz masalah. Sebagai contoh, menyenaraikan setiap susunan yang mungkin bagi 50 zarah dalam molekul yang kompleks membawa kepada konfigurasi yang berkembang sekurang-kurangnya secara faktorial, memerlukan lebih banyak memori daripada yang boleh disediakan oleh semua pusat data di Bumi."}),"\n",(0,r.jsx)(n.p,{children:"Contoh lain ialah merancang laluan penghantaran untuk 10,000 bandar: bilangan laluan yang mungkin menjadi begitu besar sehingga, walaupun setiap komputer yang pernah dibina menguji satu laluan per mikrosaat, pengiraan itu akan mengambil masa yang lebih lama berbanding usia semasa Matahari kita. Jumlah-jumlah ini bukan sekadar besar; ia berkembang secara eksponen, bermakna setiap zarah atau bandar tambahan melipatgandakan beban pengkomputeran jauh melebihi penskalaan mudah."}),"\n",(0,r.jsx)(n.p,{children:"Kita boleh terus menambah GPU, tetapi memanipulasi jumlah data yang besar sedemikian sudah menggunakan megawatt kuasa dan memerlukan kemudahan seukuran gudang. Pada titik tertentu, perkakasan klasik tidak dapat berskala lebih jauh dengan cara yang praktikal atau berpatutan. Inilah sebabnya penyelidik beralih kepada pemproses kuantum, yang menyimpan maklumat dalam superposisi dan kadangkala boleh menangani masalah pertumbuhan eksponen ini secara langsung, menyelesaikan kes-kes khusus yang tidak dapat diselesaikan oleh mesin klasik dalam jangka masa yang munasabah."}),"\n",(0,r.jsx)(n.p,{children:"HPC akhirnya mencapai had asas yang ditentukan oleh kombinatorik dan termodinamik. Pengkomputeran kuantum tidak menghapuskan had tersebut, tetapi kadangkala boleh memintas had tersebut dalam senario yang sangat spesifik."}),"\n",(0,r.jsx)(n.h2,{id:"mengapa-bukan-kuantum-sahaja",children:"Mengapa bukan kuantum sahaja?"}),"\n",(0,r.jsx)(n.p,{children:"Jika pengkomputeran kuantum boleh memintas had tertentu dalam pengkomputeran klasik, mengapa kita tidak bergantung sepenuhnya kepada komputer kuantum? Sebab pertama dan paling jelas ialah komputer kuantum masih memerlukan mesin klasik untuk berfungsi. Tugas-tugas seperti mengkompilasi dan memasukkan litar ke dalam pemproses kuantum, menyimpan hasil pengukuran, dan menjalankan pasca-pemprosesan asas semuanya dilakukan oleh sistem pengkomputeran klasik."}),"\n",(0,r.jsx)(n.p,{children:"Jadi mengapa kita juga memerlukan pengkomputeran prestasi tinggi? Terdapat beberapa sebab. Banyak aplikasi semasa dan yang dijangkakan dalam pengkomputeran kuantum menangani masalah dengan ruang carian yang sangat besar. Algoritma kuantum sering boleh mengurangkan saiz ruang ini dengan ketara, tetapi dalam praktiknya masalah yang tinggal masih mungkin cukup besar untuk mendapat manfaat daripada sumber HPC. Tambahan pula, terdapat algoritma yang mengimbangi kekuatan HPC dan pengkomputeran kuantum, meletakkan cukup kerja pada HPC untuk menjadikan keseluruhan algoritma lebih teguh terhadap kesan bunyi kuantum."}),"\n",(0,r.jsx)(n.p,{children:"Contoh konkrit ialah algoritma sample-based quantum diagonalization (SQD). Algoritma ini, yang akan diterokai dalam Pelajaran 4, menunjukkan bagaimana HPC dan pengkomputeran kuantum boleh saling melengkapi dalam praktik. Untuk latar belakang tambahan, lihat kursus Quantum Diagonalization Algorithms di IBM Quantum Learning."}),"\n",(0,r.jsx)(n.h2,{id:"new-architecture",children:"Seni bina baharu"}),"\n",(0,r.jsx)(n.p,{children:"IBM telah memperkenalkan seni bina rujukan pengkomputeran super berpusatkan kuantum (QCSC) yang menggariskan bagaimana pemproses kuantum (QPU) boleh diintegrasikan terus dengan CPU dan GPU dalam persekitaran HPC moden. Pendekatan ini didorong oleh aliran kerja hibrid kuantum-klasik yang berjaya\u2014seperti menggunakan kaedah sample-based quantum diagonalization (SQD) untuk simulasi molekul\u2014yang sudah menunjukkan ketepatan setanding dengan teknik klasik lanjutan."}),"\n",(0,r.jsx)(n.p,{children:"Seni bina ini direka untuk menjadi terbuka, modular, dan boleh disusun atur supaya sumber kuantum boleh disambungkan ke dalam aliran kerja HPC sedia ada tanpa memerlukan keseluruhan tindanan yang baharu. Integrasi awal dengan sistem seperti RIKEN dan Fugaku menunjukkan bahawa aliran kerja hibrid peringkat pengeluaran sudah boleh dilaksanakan. Ia menyediakan rangka kerja jangka panjang untuk mengembangkan reka bersama kuantum-klasik dalam dekad akan datang."}),"\n",(0,r.jsx)(n.p,{children:(0,r.jsx)(n.img,{alt:"&quot;Image showing full quantum plus HPC architecture.&quot;",src:e(31361).A+"",width:"3840",height:"2160"})}),"\n",(0,r.jsx)(n.p,{children:"Tindanan ini merangkumi lapisan aplikasi yang menguraikan masalah merentasi komponen klasik dan kuantum, perisian tengah yang menghubungkan model pengaturcaraan klasik dengan penjanaan litar kuantum (contohnya, melalui antara muka Qiskit yang dikemas kini), dan lapisan pengorkestraan sistem yang mengurus penjadualan sumber hibrid menggunakan alat seperti Quantum Resource Management Interface (QRMI)."}),"\n",(0,r.jsx)(n.p,{children:"Pada peringkat perkakasan, seni bina ini mentakrifkan tiga peringkat:"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"Sistem kuantum dengan QPU dan masa jalan klasik kependaman rendah (FPGA/ASIC)."}),"\n",(0,r.jsx)(n.li,{children:"Sistem skala-naik CPU/GPU yang ditempatkan berhampiran dan disambungkan melalui interhubung hampir-masa untuk tugas seperti pengurangan ralat."}),"\n",(0,r.jsx)(n.li,{children:"Sistem skala-keluar yang menyediakan pengkomputeran klasik fleksibel untuk pra-pemprosesan, pasca-pemprosesan, dan beban kerja hibrid."}),"\n"]}),"\n",(0,r.jsxs)(n.p,{children:["Secara keseluruhannya, IBM menempatkan seni bina QCSC sebagai peta jalan praktikal untuk pusat HPC mula menggabungkan perkakasan kuantum sebenar, membolehkan algoritma hibrid yang lebih berkuasa, dan menyediakan infrastruktur untuk sistem kuantum toleran-ralat pada masa hadapan. Untuk maklumat lanjut tentang seni bina ini, lihat ",(0,r.jsx)(n.a,{href:"https://research.ibm.com/blog/quantum-centric-supercomputing-system-reference-architecture",children:"artikel ini"}),"."]}),"\n",(0,r.jsx)(n.h2,{id:"persediaan-yang-disyorkan",children:"Persediaan yang disyorkan"}),"\n",(0,r.jsx)(n.p,{children:"Kursus ini direka untuk profesional dan pelajar yang bekerja \u2014 atau merancang untuk bekerja \u2014 rapat dengan infrastruktur pengkomputeran prestasi tinggi (HPC) dan/atau pengkomputeran kuantum. Dengan kemajuan pesat dalam teknologi kuantum, kita menjangkakan masa depan yang hampir di mana pemproses kuantum diintegrasikan bersama sumber HPC tradisional untuk mencapai hasil yang lebih tepat dan membolehkan pendekatan baru dalam penyelesaian masalah. Kursus ini ditujukan kepada peserta yang ingin memahami cara membina dan menjalankan aliran kerja hibrid tersebut."}),"\n",(0,r.jsx)(n.p,{children:"Oleh kerana peserta mungkin datang dari latar belakang yang berbeza, kami menjangkakan dua jenis utama peserta: mereka yang sudah berpengalaman dalam HPC tetapi baru dalam pengkomputeran kuantum, dan mereka yang mahir dalam pengkomputeran kuantum tetapi baru dalam HPC. Untuk membantu semua orang mendapat manfaat maksimum daripada kursus ini, kami menyediakan cadangan persediaan untuk kedua-dua kumpulan di bawah."}),"\n",(0,r.jsx)(n.h3,{id:"for-those-new-to-hpc",children:"Bagi mereka yang baru dalam HPC"}),"\n",(0,r.jsx)(n.p,{children:"Kursus ini mengandaikan kebiasaan dengan konsep teras HPC seperti pengaturcaraan memori teragih, penghantaran mesej, model pengaturcaraan selari, dan pengurusan sumber. Kita juga akan menggunakan alat seperti pengurus beban kerja Slurm. Walaupun banyak konsep ini akan diperkenalkan secara ringkas apabila diperlukan, mempunyai pendedahan awal akan menjadikan bahan lebih mudah diakses. Sumber yang berguna termasuk:"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.a,{href:"https://hpc-wiki.info/hpc/Getting_Started",children:"HPC Wiki"}),": Halaman dengan definisi dan pendekatan dalam pengkomputeran prestasi tinggi."]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.a,{href:"https://en.wikipedia.org/wiki/Slurm_Workload_Manager",children:"Halaman Wikipedia Slurm"}),": Memberikan latar belakang ringkas dan nota tentang penggunaan yang meluas."]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.a,{href:"https://slurm.schedmd.com/quickstart.html",children:"Halaman permulaan pantas Slurm"}),": Beberapa latar belakang, nota tentang permulaan, dan senarai arahan Slurm asas."]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.a,{href:"https://mpitutorial.com/tutorials/mpi-hello-world/",children:"Tutorial MPI"}),": Hello World asas menggunakan MPI."]}),"\n"]}),"\n",(0,r.jsxs)(n.p,{children:["Sumber tambahan juga disediakan dalam ",(0,r.jsx)(n.a,{href:"https://github.com/christopherporter1/hpc-course-demos",children:"repositori GitHub ini."})]}),"\n",(0,r.jsx)(n.h3,{id:"for-those-new-to-quantum",children:"Bagi mereka yang baru dalam kuantum"}),"\n",(0,r.jsx)(n.p,{children:"Kursus ini akan menggunakan alat dan konsep asas daripada pengkomputeran kuantum dengan ulasan pengenalan yang minimum. Kami mengesyorkan agar peserta mempunyai sekurang-kurangnya pengetahuan kerja tentang Qiskit, kebiasaan dengan get dan litar kuantum, dan sedikit pendedahan kepada algoritma berasaskan pensampelan. Sumber yang disenaraikan di bawah sepatutnya memberikan persediaan yang berguna."}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.a,{href:"/guides/composer",children:"Panduan IBM Quantum\xae Composer"}),": Panduan melalui Composer, alat pengaturcaraan kuantum bergrafik yang membolehkan Anda menyeret dan menjatuhkan operasi untuk membina litar kuantum dan menjalankannya pada perkakasan kuantum."]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.a,{href:"https://docs.quantum.ibm.com/guides",children:"Pengenalan kepada Qiskit"}),": Satu set panduan untuk membantu Anda memasang dan mengkonfigurasi Qiskit."]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.a,{href:"/guides/hello-world",children:"Hello world"}),": Tutorial ringkas mengenai Qiskit di mana Anda menyediakan dan menjalankan program kuantum pertama Anda."]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.a,{href:"/learning/courses/quantum-diagonalization-algorithms",children:"Algoritma pendiagonalan kuantum"}),": Kursus yang merangkumi beberapa jenis algoritma kuantum, termasuk SQD yang akan digunakan dalam kursus ini."]}),"\n"]}),"\n",(0,r.jsxs)(n.p,{children:["Sumber tambahan juga disediakan dalam ",(0,r.jsx)(n.a,{href:"https://github.com/christopherporter1/hpc-course-demos",children:"repositori GitHub ini"}),"."]}),"\n",(0,r.jsxs)(n.p,{children:["Peserta dari semua latar belakang mungkin mendapati ",(0,r.jsx)(n.a,{href:"/guides/slurm-plugin",children:"panduan ini"})," berguna; ia merangkumi plugin SPANK untuk pengurusan sumber kuantum dan beberapa patah perkataan tentang Slurm."]}),"\n",(0,r.jsx)(n.p,{children:'Terdapat beberapa cara di mana keunikan pengkomputeran kuantum menjadikannya berbeza secara prosedural daripada sumber pengkomputeran klasik dengan cara yang material untuk kursus ini. Sebagai contoh, tidak ada analog kuantum yang baik untuk RAM. Maklumat disimpan dan diproses dalam keadaan qubit itu sendiri. Walaupun pengukuran boleh membolehkan beberapa ciri qubit direkod secara klasik, pengukuran sedemikian memusnahkan banyak kekayaan keadaan kuantum, termasuk superposisi dan jalinan. Selanjutnya, sumber pengkomputeran kuantum pada masa ini tidak ditempatkan pada nod yang sama seperti sumber HPC lain, dan pengguna sumber kuantum sering tidak mempunyai tahap kawalan penjadualan yang sama seperti yang mungkin mereka ada ke atas sumber HPC klasik. Realiti-realiti ini akan diulang dalam pelajaran yang sesuai. Tetapi kesimpulan di sini ialah komputer kuantum akan mengubah dunia dan mesti diintegrasikan dengan HPC, tetapi ia bukan "sekadar satu lagi" sumber HPC yang boleh dikawal dan digunakan dengan cara yang sama seperti CPU, GPU, dan lain-lain. Komputer kuantum mengubah cara kita boleh mendekati banyak masalah pengkomputeran.'}),"\n",(0,r.jsx)(n.h2,{id:"tentang-kursus-ini",children:"Tentang kursus ini"}),"\n",(0,r.jsx)(n.p,{children:"Menjelang akhir kursus ini, Anda akan dapat melakukan lebih daripada sekadar mengulang istilah teknikal \u2014 Anda akan memahami cara menguruskan aliran kerja hibrid moden yang menugaskan sub-tugas tertentu kepada pemproses kuantum sementara CPU dan GPU mengendalikan kerja yang tinggal. Anda akan belajar cara menulis skrip untuk kerja yang beralih dengan lancar antara nod klasik dan QPU, mentafsir hasilnya dengan tepat, dan mengenal pasti di mana pecutan kuantum benar-benar boleh meningkatkan pengiraan (dan di mana tidak boleh). Sama pentingnya, Anda akan berlatih mengekalkan minda pertumbuhan: dalam bidang yang baru dan berkembang pesat, tiada sesiapa yang mempelajari segalanya sekaligus, dan kemajuan sebenar datang daripada lelaran, bereksperimen, dan bertanya soalan.\nKursus ini dibahagikan kepada 5 bab, yang merangkumi topik berikut:"}),"\n",(0,r.jsx)(n.h3,{id:"garis-besar-kursus",children:"Garis besar kursus"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"Pelajaran 1 - Pelajaran ini merangkumi latar belakang dan motivasi"}),"\n",(0,r.jsx)(n.li,{children:"Pelajaran 2 - Sumber pengkomputeran dan pengurusannya"}),"\n",(0,r.jsx)(n.li,{children:"Pelajaran 3 - Model pengaturcaraan yang merangkumi persekitaran pengkomputeran heterogen"}),"\n",(0,r.jsx)(n.li,{children:"Pelajaran 4 - Algoritma kuantum untuk aliran kerja hibrid, khususnya SQD"}),"\n",(0,r.jsx)(n.li,{children:"Pelajaran 5 - Pandangan dan hala tuju masa depan"}),"\n"]}),"\n",(0,r.jsx)(n.p,{children:"Anggap kursus ini sebagai landasan pelancaran Anda \u2014 tempat di mana Anda membina kit alat mental dan keyakinan diri untuk meneroka sempadan kuantum-klasik lama selepas Anda menamatkan pelajaran terakhir."}),"\n",(0,r.jsx)(n.h2,{id:"rujukan",children:"Rujukan"}),"\n",(0,r.jsxs)(n.p,{children:["[1] ",(0,r.jsx)(n.a,{href:"https://www.hpcwire.com/off-the-wire/gordon-bell-prize-awarded-to-ibm-and-leading-university-researchers/",children:"https://www.hpcwire.com/off-the-wire/gordon-bell-prize-awarded-to-ibm-and-leading-university-researchers/"})]})]})}function d(a={}){const{wrapper:n}={...(0,s.R)(),...a.components};return n?(0,r.jsx)(n,{...a,children:(0,r.jsx)(l,{...a})}):l(a)}},31361(a,n,e){e.d(n,{A:()=>i});const i=e.p+"assets/images/qcsc-arch-b67d02090be260d56c28277242549d1c.avif"},28453(a,n,e){e.d(n,{R:()=>t,x:()=>u});var i=e(96540);const r={},s=i.createContext(r);function t(a){const n=i.useContext(s);return i.useMemo(function(){return"function"==typeof a?a(n):{...n,...a}},[n,a])}function u(a){let n;return n=a.disableParentContext?"function"==typeof a.components?a.components(r):a.components||r:t(a.components),i.createElement(s.Provider,{value:n},a.children)}}}]);